
const metrics=[{"title": "Total gross foreign investment inflows", "change": "124.8", "unit": "USD billion", "period": "FY2013–14 → FY2024–25", "before": "36.05", "after": "81.04", "source": "https://www.pib.gov.in/PressReleasePage.aspx?PRID=2131716&lang=1&reg=1", "note": "Provisional last period; gross inflows, not net FDI. No causal attribution to one government."}, {"title": "Extreme poverty, legacy $2.15 line (2017 PPP)", "change": "-13.9", "unit": "% population", "period": "2011–12 → 2022–23", "before": "16.2", "after": "2.3", "source": "https://www.worldbank.org/en/news/factsheet/2025/06/05/june-2025-update-to-global-poverty-lines", "note": "World Bank harmonized historical 2011–12 MMRP survey; do not mix with newer 2021 PPP poverty line. Pre-2014 to post-2014 comparison is not attribution."}, {"title": "Rural monthly real consumption per person", "change": "45.38", "unit": "₹ at 2011–12 prices", "period": "2011–12 → 2023–24", "before": "1430", "after": "2079", "source": "https://www.pib.gov.in/PressReleasePage.aspx?PRID=2150425&lang=2&reg=48", "note": "HCES method differs between older and newer surveys; cross-period comparability cannot be treated as exact."}, {"title": "Urban monthly real consumption per person", "change": "38.1", "unit": "₹ at 2011–12 prices", "period": "2011–12 → 2023–24", "before": "2630", "after": "3632", "source": "https://www.pib.gov.in/PressReleasePage.aspx?PRID=2150425&lang=2&reg=48", "note": "HCES method differs between rounds, so this is indicative rather than fully harmonised."}, {"title": "Rural monthly nominal consumption per person", "change": "9.25", "unit": "₹ current prices", "period": "2022–23 → 2023–24", "before": "3773", "after": "4122", "source": "https://www.pib.gov.in/PressReleasePage.aspx?PRID=2150425&lang=2&reg=48", "note": "Current-price comparison, not real spending power."}, {"title": "Urban monthly nominal consumption per person", "change": "8.31", "unit": "₹ current prices", "period": "2022–23 → 2023–24", "before": "6459", "after": "6996", "source": "https://www.pib.gov.in/PressReleasePage.aspx?PRID=2150425&lang=2&reg=48", "note": "Current-price comparison, not real spending power."}, {"title": "Headline CPI inflation (revised base)", "change": "0.71", "unit": "% YoY", "period": "August 2026 → September 2026", "before": "4.83", "after": "5.54", "source": "https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2322244&lang=2&reg=48", "note": "September provisional, August final; 2024=100 CPI; monthly change in annual inflation rates, not change in CPI price level."}, {"title": "Food inflation (revised base)", "change": "1.77", "unit": "% YoY", "period": "August 2026 → September 2026", "before": "5.97", "after": "7.74", "source": "https://www.pib.gov.in/PressReleseDetailm.aspx?PRID=2322244&lang=2&reg=48", "note": "September provisional, August final; 2024=100 base; this is monthly change in year-on-year food inflation."}];
